package science.transductive.nudge.core;
import java.util.*;import static science.transductive.nudge.core.Models.*;
public final class CoreTests {static int n=0;static void ok(boolean x,String name){n++;if(!x)throw new AssertionError(name);System.out.println("PASS "+name);}static void throwsIAE(Runnable r,String name){n++;try{r.run();throw new AssertionError(name+" did not throw");}catch(IllegalArgumentException e){System.out.println("PASS "+name+" -> "+e.getMessage());}}
static String sample(long now){return "{\"protocol\":\"NUDGE_PROTOCOL/1\",\"interactionId\":\"i-1\",\"issuedAtMs\":"+(now-1000)+",\"triggerAtMs\":"+(now+5000)+",\"expiresAtMs\":"+(now+60000)+",\"title\":\"Fast check\",\"readyGate\":true,\"readyPrompt\":\"DO NOT THINK. READY?\",\"prompt\":\"HOW DO YOU FEEL?\",\"attention\":\"URGENT\",\"capture\":\"CHOICE\",\"countdownMs\":2000,\"requiresExactTiming\":true,\"requestFullScreen\":true,\"choices\":[{\"id\":\"good\",\"label\":\"GOOD\"},{\"id\":\"tense\",\"label\":\"TENSE\"}]}";}
public static void main(String[]args){final long now=1800000000000L;final InteractionSpec s=Protocol.parseInteraction(sample(now));ok(s.choices().size()==2&&s.attention()==Attention.URGENT&&s.triggerAtMs()==now+5000&&s.readyGate(),"parse_interaction_ready_gate_and_timing");String serialized=Protocol.stringifyInteraction(s);InteractionSpec s2=Protocol.parseInteraction(serialized);ok(s2.equals(s),"interaction_exact_roundtrip");Protocol.validateForNow(s,now,Collections.<String>emptySet());ok(true,"valid_now");String expiredJson=sample(now).replace(Long.toString(now+5000),Long.toString(now-500)).replace(Long.toString(now+60000),Long.toString(now-1));final InteractionSpec expired=Protocol.parseInteraction(expiredJson);throwsIAE(new Runnable(){public void run(){Protocol.validateForNow(expired,now,Collections.<String>emptySet());}},"expiry_rejected");throwsIAE(new Runnable(){public void run(){Protocol.validateForNow(s,now,Collections.singleton("i-1"));}},"replay_rejected");throwsIAE(new Runnable(){public void run(){Protocol.parseInteraction(sample(now).replace("NUDGE_PROTOCOL/1","NUDGE_PROTOCOL/2"));}},"unknown_major_rejected");throwsIAE(new Runnable(){public void run(){Protocol.parseInteraction(sample(now).replace("i-1","bad id with spaces"));}},"unsafe_id_rejected");ResponseEvent e=Protocol.choiceEvent(s,"ev-1","good",now);ok("good".equals(e.choiceId()),"choice_event");throwsIAE(new Runnable(){public void run(){Protocol.choiceEvent(s,"ev-x","bogus",now);}},"unknown_choice_rejected");CapabilitySnapshot low=new CapabilitySnapshot(true,false,false,false,true,false,true);Plan p=Protocol.plan(s,low);ok(p.delivery()==Delivery.HEADS_UP&&p.downgrades().contains("full_screen_unavailable"),"fullscreen_downgrades_to_heads_up");ok(p.timing()==Timing.INEXACT_ALARM&&p.downgrades().contains("exact_alarm_unavailable"),"exact_alarm_downgrade");String audio=sample(now).replace("\"capture\":\"CHOICE\"","\"capture\":\"AUDIO\"").replace("[{\"id\":\"good\",\"label\":\"GOOD\"},{\"id\":\"tense\",\"label\":\"TENSE\"}]","[]");InteractionSpec a=Protocol.parseInteraction(audio);Plan bg=Protocol.plan(a,new CapabilitySnapshot(true,true,true,true,true,true,false));ok(!bg.canStartAudio()&&bg.downgrades().contains("audio_requires_visible_user_action"),"background_audio_refused");Plan fg=Protocol.plan(a,new CapabilitySnapshot(true,true,true,true,true,true,true));ok(fg.canStartAudio(),"visible_audio_allowed");ResponseEvent ae=Protocol.audioEvent(a,"ev-audio","audio/abc",now);ok("audio/abc".equals(ae.audioRef()),"audio_event");ReplayGuard rg=new ReplayGuard(2);ok(rg.accept("a")&&!rg.accept("a")&&rg.accept("b")&&rg.accept("c")&&rg.accept("a"),"bounded_event_dedupe");Receipt r=Protocol.receipt(s,ReceiptStatus.UNKNOWN_OUTCOME,now,"delivery state not observable",p);ok(Protocol.stringifyReceipt(r).contains("UNKNOWN_OUTCOME"),"unknown_outcome_receipt");ok(Protocol.stringifyResponse(e).contains("\"eventId\":\"ev-1\""),"response_serialization");System.out.println("CORE_TESTS_PASS="+n);}}
